def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seeds = [[] for _ in range(w)]
    bar_rows = []

    # Fill the single-cell gaps in horizontal bars; each gap also starts
    # a vertical ray extending upward.
    for r in range(h):
        has_bar = False
        for c in range(1, w - 1):
            color = grid[r][c - 1]
            if color != 0 and grid[r][c] == 0 and grid[r][c + 1] == color:
                out[r][c] = color
                seeds[c].append((r, color))
            if color != 0 and grid[r][c] == color:
                has_bar = True
        if has_bar:
            bar_rows.append(r)

    # The vertical markers lie below the lowest horizontal bar.
    if bar_rows:
        last_bar = max(bar_rows)
        for r in range(last_bar + 1, h):
            for c in range(w):
                if grid[r][c] != 0:
                    seeds[c].append((r, grid[r][c]))

    # Pre-mark every seed so rays stop when they meet another seed.
    for c in range(w):
        for r, color in seeds[c]:
            out[r][c] = color

    # Extend each seed upward through empty cells, stopping at any colored cell.
    for c in range(w):
        for r, color in sorted(seeds[c], reverse=True):
            rr = r - 1
            while rr >= 0 and out[rr][c] == 0:
                out[rr][c] = color
                rr -= 1

    return out
